def compact_ranges(values: list[int]) -> str:
    numbers = sorted(set(values))
    result = []
    i = 0

    while i < len(numbers):
        j = i
        while j + 1 < len(numbers) and numbers[j + 1] == numbers[j] + 1:
            j += 1

        if j - i >= 2:
            result.append(f"{numbers[i]}-{numbers[j]}")
        else:
            result.extend(str(number) for number in numbers[i : j + 1])

        i = j + 1

    return ",".join(result)

